51: if(state.ball>=100){$('#resultBanner').textContent=`TOUCHDOWN! Seven points for ${teamNickname('home')}.`;score('home',7,`Touchdown, ${teamNickname('home')}! ${yards} yards to the house.`);render();return}
52: if(state.ball<=0){$('#resultBanner').textContent=`Safety! ${teamNickname('away')} scores 2.`;state.away+=2;addFeed(`Safety! ${teamNickname('away')} scores two.`,'score');finishDrive('home');render();return}
