.mode-title{margin:6px 0 0;font-size:22px;letter-spacing:-.04em}.match-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.match-card{min-height:96px;padding:10px 8px;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:7px;text-align:left;background:#0a1723;border:1px solid #2a3e50;border-radius:11px;transition:transform .15s,border-color .15s,background .15s;touch-action:manipulation}.match-card:hover,.match-card.picked{transform:translateY(-2px);border-color:var(--lime);background:#172a38}.match-card.picked{box-shadow:inset 0 0 0 1px #c8f16955}.match-card-icon{font-size:21px}.match-card b{font-size:11px;line-height:1.2}.match-card small{font-size:8px;color:#91a4b5;line-height:1.2}
