.field-wrap{padding:0 14px 14px}.field{height:250px;position:relative;border-radius:10px;overflow:hidden;background:#174b35;border:1px solid #397455;box-shadow:inset 0 0 45px #09291e}.portrait-field{position:absolute;inset:0;display:grid;grid-template-rows:8% 84% 8%;background:repeating-linear-gradient(0deg,transparent 0,transparent calc(10% - 1px),rgba(235,255,239,.28) calc(10% - 1px),rgba(235,255,239,.28) 10%),linear-gradient(90deg,#1d563b,#15452f)}.endzone{position:relative;z-index:1;display:grid;place-items:center;background:repeating-linear-gradient(45deg,#153f2f,#153f2f 8px,#1a4935 8px,#1a4935 16px);color:#d4ead7;font-size:8px;font-weight:900;letter-spacing:.12em;text-shadow:0 1px 3px #000}.endzone-away{grid-row:1;border-bottom:1px solid #a7d6ad66}.endzone-home{grid-row:3;border-top:1px solid #a7d6ad66}.field-grid{grid-row:2;background:repeating-linear-gradient(90deg,transparent 0,transparent calc(10% - 1px),rgba(235,255,239,.2) calc(10% - 1px),rgba(235,255,239,.2) 10%);position:relative}.field-grid:before,.field-grid:after{content:"";position:absolute;left:2%;right:2%;height:1px;background:#e4ffe5aa}.field-grid:before{top:0}.field-grid:after{bottom:0}.yard-stamps{position:absolute;z-index:2;inset:8% 0;display:flex;flex-direction:column;justify-content:space-evenly;align-items:flex-end;padding-right:8px;color:#e5f7e599;font-size:8px;font-style:normal;font-weight:900;text-shadow:0 1px 2px #09291e}.p-ball,.p-first{position:absolute;z-index:3;transform:translate(-50%,-50%);transition:top .72s cubic-bezier(.22,.75,.22,1)}.p-ball{left:50%;font-size:19px;filter:drop-shadow(0 2px 3px #09291e);will-change:top}.p-first{left:0;width:100%;height:3px;background:#ffd84d;box-shadow:0 0 9px #ffd84dcc}.p-first:before{content:"TO GAIN";position:absolute;left:8px;top:50%;transform:translateY(-50%);padding:2px 4px;border-radius:3px;background:#172418;color:#ffe77e;font-size:7px;font-weight:900;letter-spacing:.08em;white-space:nowrap}.p-dice{position:absolute;z-index:5;left:50%;top:50%;display:flex;align-items:center;gap:7px;padding:8px 11px;border:1px solid #f7e5a5;border-radius:12px;background:#102019eF;color:#152018;box-shadow:0 5px 18px #06120cb3;opacity:0;pointer-events:none;transform:translate(-50%,-50%) scale(.55)}.p-dice.show{animation:dice-burst 1.15s cubic-bezier(.16,.84,.3,1) both}.p-dice span{display:grid;place-items:center;width:34px;height:34px;border-radius:7px;background:#fff8df;color:#1d3022;font-size:20px;font-weight:950;box-shadow:0 3px 0 #c6b77f}.p-dice b{color:#ffe27a;font-size:9px;letter-spacing:.08em;white-space:nowrap}.field-foot{display:none}.drive-info{display:flex;gap:9px;padding:0 18px 15px}@keyframes dice-burst{0%{opacity:0;transform:translate(-50%,-50%) scale(.35) rotate(-12deg)}18%{opacity:1;transform:translate(-50%,-50%) scale(1.12) rotate(5deg)}32%{transform:translate(-50%,-50%) scale(.96) rotate(-2deg)}48%,74%{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0)}100%{opacity:0;transform:translate(-50%,-56%) scale(.9)}}
