  const td = await page.evaluate(() => ({
    score: document.querySelector('#homeScore').innerText,
    conversionVisible: document.querySelector('#cardMatch').innerText.includes('Go for one or two?'),
    audioStarts: window.__audioStarts,
    mobileOverflow: document.documentElement.scrollWidth > innerWidth,
    ball: document.querySelector('#ballOn').innerText,
    buttons: [...document.querySelectorAll('.decision-card')].map(b=>Math.round(b.getBoundingClientRect().height)),
  }));
  await page.screenshot({ path: '/tmp/opencode/sunday-showdown-check.jpg', type: 'jpeg', quality: 72 });
  console.log('TOUCHDOWN', JSON.stringify({td,errors}));
  await page.reload({ waitUntil: 'load' });
  await page.locator('[data-mode="cpu"]').click();
  await page.evaluate(() => { const seq=[.5,0,0,0]; let i=0; Math.random=()=>seq[i++%seq.length]; });
  await page.locator('[data-card="3"]').click();
  await page.locator('[data-action="snap"]').click();
  await page.waitForTimeout(100);
  const turnover = await page.evaluate(() => ({
    feed: document.querySelector('#feed').innerText.slice(0,160),
    audioStarts: window.__audioStarts,
    possessionLabel: document.querySelector('#possessionLabel').innerText,
    turnovers: document.querySelector('#turnoverStat').innerText,
  }));
  console.log('TURNOVER', JSON.stringify({turnover,errors}));
} finally { await browser.close(); }
